<script setup lang="ts">
import {ref} from 'vue'
import {api,post} from '../api'
import {usePolling} from '../usePolling'
import {number,time} from '../format'
type Quote={version:string;symbol:string;side:string;status:string;reason:string;asOf:string;requestedQuantity:number;quantity:number|null;remainder:number|null;vwap:number|null;estimatedFill:number|null;fee:number|null;spreadBps:number|null;impactBps:number|null;roundedStop:number|null;plannedLossIncludingCosts:number|null;bookAt:string|null}
type Foundation={asOf:string;mode:string;rulesAt:string|null;rulesCount:number;storedFundingPayments:number|null;model:{version:string;feeRate:number;residualSlippageRate:number};
 symbols:{symbol:string;rules:{tickSize:number;stepSize:number;marketStepSize:number;minimumNotional:number;issue:string|null}|null;buy100Usdt:Quote|null;sell100Usdt:Quote|null;fundingRecords:number|null;fundingThrough:string|null;adjustedFundingIntervalHours:number|null;lastObservedIntervalHours:number|null;nextFundingAt:string|null;error:string|null}[];
 fundingAudits:{positionId:string;symbol:string;direction:string;status:string;reason:string;knownThrough:string|null;completeSignedCost:number|null;observedSignedCost:number;legacyRecordedCost:number;payments:{fundingAt:string;quantity:number;rate:number;markPrice:number;signedCost:number}[]}[];
 heldExitQuotes:Quote[];notices:string[]}
const data=ref<Foundation|null>(null)
const {error}=usePolling(async signal=>{data.value=await api<Foundation>('/api/execution/status',{signal})},15000)
const symbol=ref('BTCUSDT'),side=ref('Buy'),quantity=ref<number|undefined>(),stop=ref<number|undefined>(),busy=ref(false),previewError=ref(''),quote=ref<Quote|null>(null)
const label=(s:string)=>({Estimated:'成本估算',Unknown:'数据不足/失鲜',Blocked:'规则拦截',Invalid:'输入无效',ObservedWindow:'查询窗口已覆盖',Partial:'窗口未完全覆盖'}[s]??s)
async function preview(){if(busy.value)return;busy.value=true;previewError.value='';quote.value=null;try{quote.value=await post<Quote>('/api/execution/preview',{symbol:symbol.value.trim().toUpperCase(),side:side.value,quantity:quantity.value??0,stopPrice:stop.value??null})}catch(e){previewError.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
</script>
<template><section class="detail execution-foundation" aria-label="执行基础核验"><h2>成本证据对照</h2>
<p>这里核对盘口、交易规则和资金费来源。实际模拟成交与记账由当前执行负责，本模块只展示证据。</p>

<p v-if="error" class="radar-notice">读取失败：{{error}}。已有内容为上次成功读取的缓存。</p>
<p v-if="data">模型 {{data.model.version}} · 规则记录 {{data.rulesCount}} 条（含非交易状态） · 规则抓取 {{time(data.rulesAt)}} · 已去重保存资金费记录 {{data.storedFundingPayments??'Unknown'}} 条 · 本页数据 {{time(data.asOf)}}</p>
<details v-if="data"><summary>查看实际资金费、合约步长与盘口成本</summary>
<h3>持仓 / 近期平仓的资金费对照</h3>
<div class="table-scroll"><table><thead><tr><th>标的 / 方向</th><th>账本已记费用 U</th><th>实际来源已观测 U</th><th>持仓期完整核验 U</th><th>覆盖与来源</th></tr></thead><tbody><tr v-for="a in data.fundingAudits" :key="a.positionId"><td>{{a.symbol}} / {{a.direction==='Short'?'做空':'做多'}}</td><td>{{number(a.legacyRecordedCost,6)}}</td><td>{{number(a.observedSignedCost,6)}}</td><td>{{a.completeSignedCost==null?'Unknown':number(a.completeSignedCost,6)}}</td><td>{{label(a.status)}}<small>核验至 {{time(a.knownThrough)}}</small><small>{{a.reason}}</small><details><summary>结算时点 {{a.payments.length}} 条</summary><p v-for="p in a.payments" :key="p.fundingAt">{{time(p.fundingAt)}} · 数量 {{number(p.quantity,8)}} · 费率 {{number(p.rate*100,6)}}% · 标记价 {{number(p.markPrice,8)}} · 费用 {{number(p.signedCost,8)}} U</p></details></td></tr><tr v-if="!data.fundingAudits.length"><td colspan="5">尚无有效持仓生命周期或来源记录，不能认定为零资金费。</td></tr></tbody></table></div>
<p>资金费正数表示付费、负数表示收取。来源记录用于对照，原历史交易与现金不事后改写。</p>
<h3>当前持仓退出成本核验</h3><p v-for="q in data.heldExitQuotes" :key="q.symbol">{{q.symbol}} · {{q.side==='Buy'?'买入平空':'卖出平多'}} · {{label(q.status)}} · 原数量 {{number(q.requestedQuantity,8)}} → 步长取整 {{number(q.quantity,8)}}，余数 {{number(q.remainder,8)}} · 估算价 {{number(q.estimatedFill,8)}} · 手续费假设 {{number(q.fee,6)}} U<small>{{q.reason}}；盘口 {{time(q.bookAt)}}</small></p>
<h3>来源与交易约束</h3><div class="table-scroll"><table><thead><tr><th>合约</th><th>价格 / 数量步长</th><th>最低名义 U</th><th>当前100 U盘口演示</th><th>资金费历史 / 周期</th></tr></thead><tbody><tr v-for="s in data.symbols" :key="s.symbol"><td>{{s.symbol}}<small v-if="s.error">{{s.error}}</small><small v-if="s.rules?.issue">{{s.rules.issue}}</small></td><td>{{number(s.rules?.tickSize,10)}} / {{number(s.rules?.stepSize,10)}}<small>市价数量步长 {{number(s.rules?.marketStepSize,10)}}</small></td><td>{{number(s.rules?.minimumNotional,2)}}</td><td>买：{{s.buy100Usdt?label(s.buy100Usdt.status):'Unknown'}} / 卖：{{s.sell100Usdt?label(s.sell100Usdt.status):'Unknown'}}<small>点差 {{number(s.buy100Usdt?.spreadBps,3)}} bps · {{time(s.buy100Usdt?.bookAt)}}</small></td><td>{{s.fundingRecords??'Unknown'}} 条；至 {{time(s.fundingThrough)}}<small>当前调整周期 {{s.adjustedFundingIntervalHours??'未列出/Unknown'}} h；最近两次实际间隔 {{number(s.lastObservedIntervalHours,3)}} h</small><small>行情声明的下次结算 {{time(s.nextFundingAt)}}</small></td></tr></tbody></table></div>
<h3>只读核验一个数量</h3><form class="execution-form" @submit.prevent="preview"><label>已采集合约<input v-model="symbol" aria-label="核验合约" required/></label><label>订单方向<select v-model="side" aria-label="核验方向"><option value="Buy">买入</option><option value="Sell">卖出</option></select></label><label>数量<input v-model.number="quantity" type="number" min="0" step="any" aria-label="核验数量" required/></label><label>止损价（可选）<input v-model.number="stop" type="number" min="0" step="any" aria-label="核验止损价"/></label><button class="replay-action" :disabled="busy">{{busy?'计算中':'只读核验，不下单'}}</button></form>
<p v-if="previewError" class="radar-notice">{{previewError}}</p><div v-if="quote"><p>{{quote.symbol}} · {{label(quote.status)}} · {{quote.reason}}</p><p>数量 {{number(quote.quantity,8)}}；盘口VWAP {{number(quote.vwap,8)}}；含残余滑点的估算价 {{number(quote.estimatedFill,8)}}；手续费假设 {{number(quote.fee,6)}} U；止损取整 {{number(quote.roundedStop,8)}}；含往返成本的止损损失估计 {{number(quote.plannedLossIncludingCosts,6)}} U。</p><small>盘口 {{time(quote.bookAt)}}；计算 {{time(quote.asOf)}}。刷新采集后需重新核验。</small></div>
<p v-for="n in data.notices" :key="n" class="muted">{{n}}</p>
</details></section></template>
<style scoped>summary{cursor:pointer;margin:12px 0}h3{margin-top:24px}td{vertical-align:top}small{display:block;max-width:480px;margin-top:5px}.muted{opacity:.72}.execution-form{display:flex;flex-wrap:wrap;gap:12px;align-items:end}.execution-form label{display:flex;flex-direction:column;gap:7px}.execution-form input,.execution-form select{max-width:190px;padding:9px;background:#101821;color:#d8e8ec;border:1px solid #2d3a45;border-radius:5px}</style>
